<div class="portal-receipt-signature" data-receipt-signature-modal hidden>
    <div class="portal-receipt-signature__backdrop" data-receipt-signature-cancel></div>
    <section class="portal-receipt-signature__dialog" role="dialog" aria-modal="true" aria-labelledby="portal-receipt-signature-title">
        <header><div><h3 id="portal-receipt-signature-title">Confirmar recebimento</h3><p>Assine sobre a linha para confirmar que recebeu o pedido.</p></div><button type="button" data-receipt-signature-cancel aria-label="Fechar">×</button></header>
        <div class="portal-receipt-signature__pad"><canvas data-receipt-signature-canvas></canvas><i></i><button type="button" data-receipt-signature-clear>Limpar</button></div>
        <footer><button type="button" class="portal-btn portal-btn--ghost" data-receipt-signature-cancel>Cancelar</button><button type="button" class="portal-btn portal-btn--primary" data-receipt-signature-confirm disabled>Confirmar recebimento</button></footer>
    </section>
</div>
<style>
.portal-receipt-signature{position:fixed;z-index:12000;inset:0;display:grid;place-items:center;padding:16px}.portal-receipt-signature[hidden]{display:none}.portal-receipt-signature__backdrop{position:absolute;inset:0;background:rgba(15,23,42,.68);backdrop-filter:blur(4px)}.portal-receipt-signature__dialog{position:relative;width:min(650px,100%);padding:26px;border-radius:24px;background:var(--portal-card-bg,#fff);color:var(--portal-text,#0f172a);box-shadow:0 28px 80px rgba(15,23,42,.32)}.portal-receipt-signature__dialog header{display:flex;justify-content:space-between;gap:16px;margin-bottom:18px}.portal-receipt-signature__dialog h3{margin:0 0 5px}.portal-receipt-signature__dialog p{margin:0;color:var(--portal-muted,#64748b)}.portal-receipt-signature__dialog header button{width:36px;height:36px;border:0;border-radius:11px;background:rgba(148,163,184,.12);color:inherit;font-size:24px;cursor:pointer}.portal-receipt-signature__pad{position:relative;height:220px;overflow:hidden;border:1px dashed color-mix(in srgb,var(--primary) 55%,#cbd5e1);border-radius:16px;background:#fff}.portal-receipt-signature__pad canvas{position:absolute;z-index:2;inset:0;width:100%;height:100%;touch-action:none;cursor:crosshair}.portal-receipt-signature__pad i{position:absolute;z-index:1;left:9%;right:9%;bottom:28%;height:1px;background:#94a3b8}.portal-receipt-signature__pad>button{position:absolute;z-index:3;right:10px;top:10px;padding:7px 11px;border:1px solid #cbd5e1;border-radius:10px;background:#fff;color:#334155;font-weight:800;cursor:pointer}.portal-receipt-signature__dialog footer{display:flex;justify-content:flex-end;gap:10px;margin-top:18px}@media(max-width:650px){.portal-receipt-signature__dialog{padding:19px}.portal-receipt-signature__pad{height:190px}.portal-receipt-signature__dialog footer{display:grid;grid-template-columns:1fr 1fr}}
</style>
<script>
(()=>{const modal=document.querySelector('[data-receipt-signature-modal]'),canvas=modal?.querySelector('[data-receipt-signature-canvas]'),pad=canvas?.closest('.portal-receipt-signature__pad'),confirm=modal?.querySelector('[data-receipt-signature-confirm]'),clearButton=modal?.querySelector('[data-receipt-signature-clear]');if(!modal||!canvas||!pad||!confirm||!clearButton)return;const ctx=canvas.getContext('2d');let drawing=false,ink=false,resolveCurrent=null;const resize=()=>{const rect=canvas.getBoundingClientRect();if(rect.width<2||rect.height<2)return;const ratio=devicePixelRatio||1;canvas.width=Math.round(rect.width*ratio);canvas.height=Math.round(rect.height*ratio);ctx.setTransform(ratio,0,0,ratio,0,0);ctx.strokeStyle='#111827';ctx.lineWidth=2.2;ctx.lineCap='round';ctx.lineJoin='round'};const point=e=>{const rect=canvas.getBoundingClientRect();return{x:e.clientX-rect.left,y:e.clientY-rect.top}};const clear=()=>{ctx.save();ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,canvas.width,canvas.height);ctx.restore();drawing=false;ink=false;confirm.disabled=true};const close=value=>{modal.hidden=true;document.body.style.overflow='';const done=resolveCurrent;resolveCurrent=null;done?.(value)};canvas.addEventListener('pointerdown',e=>{e.preventDefault();drawing=true;ink=true;confirm.disabled=false;const p=point(e);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x+.1,p.y+.1);ctx.stroke();try{canvas.setPointerCapture(e.pointerId)}catch(error){}});canvas.addEventListener('pointermove',e=>{if(!drawing)return;e.preventDefault();const p=point(e);ctx.lineTo(p.x,p.y);ctx.stroke()});const finish=e=>{if(!drawing)return;drawing=false;try{canvas.releasePointerCapture(e.pointerId)}catch(error){}};canvas.addEventListener('pointerup',finish);canvas.addEventListener('pointercancel',finish);window.addEventListener('pointerup',finish,true);clearButton.addEventListener('click',clear);modal.querySelectorAll('[data-receipt-signature-cancel]').forEach(button=>button.addEventListener('click',()=>close(null)));confirm.addEventListener('click',()=>{if(!ink)return;close(canvas.toDataURL('image/png'))});window.collectPortalReceiptSignature=()=>new Promise(resolve=>{resolveCurrent=resolve;modal.hidden=false;document.body.style.overflow='hidden';requestAnimationFrame(()=>requestAnimationFrame(()=>{resize();clear()}))})})();
</script>
